Your expense tracker is below. Add an expense, pick the month, set a budget, and it totals by category as you go. Entries stay only while this page is open, so nothing is saved after you close it.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body{font-family:Segoe UI,Arial,sans-serif;margin:0;padding:16px;background:#f6f7f5;color:#1f2a24}
  h1{font-size:20px;margin:0 0 12px}
  .card{background:#fff;border-radius:10px;padding:12px;margin-bottom:12px;box-shadow:0 1px 3px rgba(0,0,0,.08)}
  .row{display:flex;gap:8px;flex-wrap:wrap;align-items:center}
  input,select,button{font:inherit;padding:7px 9px;border:1px solid #c9d1cb;border-radius:6px;background:#fff}
  input.grow{flex:1;min-width:110px}
  button{background:#2f7d5b;color:#fff;border:none;cursor:pointer}
  button.x{background:none;color:#b03a3a;padding:2px 8px}
  .big{font-size:24px;font-weight:600}
  .muted{color:#6b776f;font-size:13px}
  .bar{height:8px;background:#e3e8e4;border-radius:4px;overflow:hidden;margin:3px 0 9px}
  .bar div{height:100%;background:#2f7d5b}
  .over{color:#b03a3a}
  .item{display:flex;justify-content:space-between;align-items:center;padding:7px 0;border-bottom:1px solid #eef0ee}
  .item:last-child{border-bottom:none}
</style>
</head>
<body>
<h1>Monthly expenses</h1>

<div class="card">
  <div class="row">
    <label>Month <input type="month" id="month"></label>
    <label>Budget (₹) <input type="number" id="budget" min="0" value="30000" style="width:110px"></label>
  </div>
  <div class="big" id="total">₹0</div>
  <div class="muted" id="left"></div>
</div>

<div class="card">
  <div class="row">
    <input class="grow" id="name" placeholder="What was it for?">
    <input id="amt" type="number" min="0" placeholder="Amount (₹)" style="width:120px">
    <select id="cat">
      <option>Food</option><option>Rent</option><option>Travel</option>
      <option>Bills</option><option>Shopping</option><option>Other</option>
    </select>
    <input type="date" id="date">
    <button id="add">Add</button>
  </div>
  <div class="muted" id="msg"></div>
</div>

<div class="card">
  <strong>By category</strong>
  <div id="cats" style="margin-top:8px"></div>
</div>

<div class="card">
  <strong>Entries</strong>
  <div id="list"></div>
</div>

<script>
  var items = [];
  var nextId = 1;
  var inr = function(n){ return '₹' + Number(n).toLocaleString('en-IN', {maximumFractionDigits:2}); };
  var cats = ['Food','Rent','Travel','Bills','Shopping','Other'];
  var $ = function(id){ return document.getElementById(id); };

  var today = new Date();
  var iso = today.toISOString().slice(0,10);
  $('date').value = iso;
  $('month').value = iso.slice(0,7);

  function render(){
    var m = $('month').value;
    var shown = items.filter(function(i){ return i.date.slice(0,7) === m; });
    var total = shown.reduce(function(s,i){ return s + i.amt; }, 0);
    $('total').textContent = inr(total);

    var budget = Number($('budget').value) || 0;
    var left = $('left');
    if (budget > 0) {
      var diff = budget - total;
      left.className = diff < 0 ? 'muted over' : 'muted';
      left.textContent = diff >= 0 ? inr(diff) + ' left of ' + inr(budget) : inr(-diff) + ' over your budget of ' + inr(budget);
    } else { left.textContent = ''; }

    var box = $('cats');
    box.innerHTML = '';
    cats.forEach(function(c){
      var sum = shown.filter(function(i){ return i.cat === c; }).reduce(function(s,i){ return s + i.amt; }, 0);
      var pct = total ? Math.round(sum / total * 100) : 0;
      var row = document.createElement('div');
      var top = document.createElement('div');
      top.className = 'row';
      top.style.justifyContent = 'space-between';
      var a = document.createElement('span'); a.textContent = c;
      var b = document.createElement('span'); b.textContent = inr(sum) + ' (' + pct + '%)';
      top.appendChild(a); top.appendChild(b);
      var bar = document.createElement('div'); bar.className = 'bar';
      var fill = document.createElement('div'); fill.style.width = pct + '%';
      bar.appendChild(fill);
      row.appendChild(top); row.appendChild(bar);
      box.appendChild(row);
    });

    var list = $('list');
    list.innerHTML = '';
    if (!shown.length) {
      var e = document.createElement('div');
      e.className = 'muted'; e.textContent = 'Nothing added for this month yet.';
      list.appendChild(e);
    }
    shown.slice().sort(function(a,b){ return a.date < b.date ? 1 : -1; }).forEach(function(i){
      var r = document.createElement('div'); r.className = 'item';
      var l = document.createElement('div');
      var t = document.createElement('div'); t.textContent = i.name;
      var s = document.createElement('div'); s.className = 'muted'; s.textContent = i.cat + ' · ' + i.date;
      l.appendChild(t); l.appendChild(s);
      var rt = document.createElement('div');
      var amt = document.createElement('span'); amt.textContent = inr(i.amt);
      var del = document.createElement('button'); del.className = 'x'; del.textContent = 'Delete';
      del.onclick = function(){ items = items.filter(function(x){ return x.id !== i.id; }); render(); };
      rt.appendChild(amt); rt.appendChild(del);
      r.appendChild(l); r.appendChild(rt);
      list.appendChild(r);
    });
  }

  function add(){
    var name = $('name').value.trim();
    var amt = Number($('amt').value);
    var date = $('date').value;
    if (!name || !(amt > 0) || !date) { $('msg').textContent = 'Add a name, an amount above 0 and a date.'; return; }
    $('msg').textContent = '';
    items.push({id: nextId++, name: name, amt: amt, cat: $('cat').value, date: date});
    $('month').value = date.slice(0,7);
    $('name').value = ''; $('amt').value = '';
    render();
  }

  $('add').onclick = add;
  $('amt').onkeydown = $('name').onkeydown = function(e){ if (e.key === 'Enter') add(); };
  $('month').onchange = render;
  $('budget').oninput = render;
  render();
</script>
</body>
</html>
```

Here's your water tracker with a goal of 8 glasses. Tap + after each glass and − if you tap by mistake. It saves on this device when it can.

```page
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Water tracker</title>
<style>
  body { font-family: system-ui, sans-serif; margin: 0; padding: 24px; background: #eef7fb; color: #17324d; text-align: center; }
  h1 { font-size: 20px; margin: 0 0 4px; }
  .date { font-size: 13px; opacity: .7; margin-bottom: 20px; }
  .count { font-size: 48px; font-weight: 700; margin: 8px 0; }
  .glasses { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin: 16px auto; max-width: 320px; }
  .glass { width: 48px; height: 60px; border: 2px solid #4aa3d6; border-radius: 4px 4px 12px 12px; background: #fff; position: relative; overflow: hidden; }
  .glass.full::after { content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 85%; background: #4aa3d6; }
  .bar { height: 10px; max-width: 320px; margin: 12px auto; background: #d3e8f3; border-radius: 5px; overflow: hidden; }
  .fill { height: 100%; width: 0; background: #2d86bd; transition: width .25s; }
  button { font-size: 22px; width: 56px; height: 56px; border-radius: 50%; border: none; background: #2d86bd; color: #fff; margin: 8px; cursor: pointer; }
  button.minus { background: #9db9cb; }
  .msg { min-height: 24px; font-size: 15px; margin-top: 8px; }
  .reset { font-size: 13px; width: auto; height: auto; padding: 6px 14px; border-radius: 14px; background: transparent; color: #2d86bd; border: 1px solid #2d86bd; }
</style>
</head>
<body>
  <h1>Water today</h1>
  <div class="date" id="date"></div>
  <div class="count"><span id="n">0</span> / 8</div>
  <div class="bar"><div class="fill" id="fill"></div></div>
  <div class="glasses" id="glasses"></div>
  <div>
    <button class="minus" id="minus" aria-label="Remove a glass">−</button>
    <button id="plus" aria-label="Add a glass">+</button>
  </div>
  <div class="msg" id="msg"></div>
  <button class="reset" id="reset">Start over</button>

<script>
  var GOAL = 8;
  var today = new Date();
  var key = "water-" + today.toISOString().slice(0, 10);
  var count = 0;
  try { count = parseInt(localStorage.getItem(key), 10) || 0; } catch (e) {}

  document.getElementById("date").textContent = today.toDateString();

  function save() { try { localStorage.setItem(key, String(count)); } catch (e) {} }

  function draw() {
    document.getElementById("n").textContent = count;
    document.getElementById("fill").style.width = Math.min(100, count / GOAL * 100) + "%";
    var g = document.getElementById("glasses");
    g.innerHTML = "";
    for (var i = 0; i < GOAL; i++) {
      var d = document.createElement("div");
      d.className = "glass" + (i < count ? " full" : "");
      g.appendChild(d);
    }
    var m = document.getElementById("msg");
    if (count >= GOAL) m.textContent = "Goal done. Nicely hydrated! 🎉";
    else m.textContent = (GOAL - count) + " more to go";
  }

  document.getElementById("plus").onclick = function () { count++; save(); draw(); };
  document.getElementById("minus").onclick = function () { if (count > 0) count--; save(); draw(); };
  document.getElementById("reset").onclick = function () { count = 0; save(); draw(); };
  draw();
</script>
</body>
</html>
```
